"use strict";const e=require("./request.js");exports.consumeFridgeItem=function(t,r=1){return e.post(`/fridge/items/${t}/consume`,{amount:r})},exports.createFridgeItem=function(t){return e.post("/fridge/items",t)},exports.deleteFridgeItem=function(t){return e.del(`/fridge/items/${t}`)},exports.fetchFridgeItems=function(){return e.get("/fridge/items")},exports.fetchFridgeSummary=function(){return e.get("/fridge/summary")},exports.updateFridgeItem=function(t,r){return e.put(`/fridge/items/${t}`,r)};
